function observerWarScan(v,w){if(!NS.V033E2?.rawAssessment)return{target:'',score:null,reason:'UNAVAILABLE'};if(Number(w.year||0)<35)return{target:'',score:null,reason:'YEAR_GATE'};const e2=NS.V033E2.ensureState?.(w),d1=NS.V033D1?.ensureState?.(w),oldEst=e2?JSON.parse(JSON.stringify(e2.estimates||{})):null,oldRange=e2?.stats?Number(e2.stats.rangeAssessments||0):null,oldIntel=d1?.stats?Number(d1.stats.intelAssessments||0):null;let best=null;try{for(const b of w.activeVillages||[]){if(Number(b.id)===Number(v.id))continue;const a=NS.V033E2.rawAssessment(v,b,w,'E4_OBSERVER_SCAN');if(a&&(!best||Number(a.score)>Number(best.a.score)))best={b,a};}}catch(_){best=null;}finally{if(e2&&oldEst)e2.estimates=oldEst;if(e2?.stats&&oldRange!=null)e2.stats.rangeAssessments=oldRange;if(d1?.stats&&oldIntel!=null)d1.stats.intelAssessments=oldIntel;}const intents=(d1?.intents||[]).filter(x=>Number(x.nationId)===Number(v.id)&&['ASSESSING','PREPARING','READY'].includes(String(x.phase))),wars=NS.V033D?.warsForNation?.(w,v.id)||[];let reason='NO_ASSESSMENT';if(wars.length)reason='AT_WAR';else if(intents.length)reason='INTENT_ACTIVE';else if(best)reason=Number(best.a.score)<68?'TOP_SCORE_BELOW_68':'NO_INTENT_GATE_OR_REVIEW_TIMING';return{target:best?.b?.name||'',targetId:best?.b?.id??'',score:best?+Number(best.a.score||0).toFixed(2):null,reason};}
function attach(w,src=null){w=NS.V033E3?.attachWorld?.(w,src)||w;if(!w)return w;const fresh=!src&&Number(w.year||1)===1&&Number(w.season||0)===0&&Number(w.day||1)===1&&!w.v33e4;for(const v of w.villages||[]){for(const p of v.residents||[])ensurePerson(p,v,w);if(fresh)for(const p of v.residents||[])rerollFreshPersonName(p,v);}w.v33e4=w.v33e4||{revision:REV,cultureFoundation:true,cultureMix:true,derivedCultureSchema:true,maxOutputPenalty:.08};w.v33e4.revision=REV;w.v33e4CultureAttached=true;return w;}
