const harvestPrev=NS.Tile.prototype.harvest;
NS.Tile.prototype.harvest=function(kind,amount,day){const a=NS._v32fActiveAct;if(a?.p&&a?.v&&a?.w&&['food','wood','stone','gold','iron_ore'].includes(String(kind))){ensurePerson(a.p,a.v,a.w);amount=Number(amount||0)*outputMultiplier(a.p,a.v,a.w)*(NS.V033E5?.tileProductionMultiplier?.(this,a.w)??1);}return harvestPrev.call(this,kind,amount,day);};
const depositPrev=NS.Village.prototype.depositAt;
NS.Village.prototype.depositAt=function(tileId,kind,amount){const a=NS._v32fActiveAct;if(a?.p&&a?.v===this&&a?.w&&a.p.job==='철공'&&['iron','tools'].includes(String(kind)))amount=Number(amount||0)*outputMultiplier(a.p,this,a.w)*(NS.V033E5?.tileProductionMultiplier?.(a.w.map?.get?.(Number(tileId)),a.w)??1);return depositPrev.call(this,tileId,kind,amount);};
function tileCultureMap(w){const m=new Map();for(const v of w.activeVillages||[]){for(const p of v.residents||[]){if(!p.alive)continue;ensurePerson(p,v,w);let o=m.get(Number(p.homeTileId));if(!o){o={n:0,mix:{}};m.set(Number(p.homeTileId),o);}o.n++;for(const r of p.cultureMix)o.mix[r.id]=(o.mix[r.id]||0)+r.share;}}for(const o of m.values()){for(const id of Object.keys(o.mix))o.mix[id]/=Math.max(1,o.n);o.normalized=normalizeMix(o.mix);}return m;}
function drawCulture(ui){if(ui.mapLayer!=='culture33E4')return;const c=ui.q?.('worldCanvas'),g=ui._mapGeom;if(!c||!g)return;const ctx=c.getContext('2d'),{cell,ox,oy}=g,w=ui.world,tm=tileCultureMap(w);ctx.save();for(const[id,o]of tm){const t=w.map.get(id);if(!t)continue;const p=primary(o.normalized),col=CULTURES[p.id]?.color||'#aaa',alpha=.22+.46*p.share;ctx.globalAlpha=alpha;ctx.fillStyle=col;ctx.fillRect(ox+t.x*cell,oy+t.y*cell,cell,cell);ctx.globalAlpha=1;if(cell>22){ctx.strokeStyle='rgba(255,255,255,.15)';ctx.lineWidth=1;ctx.strokeRect(ox+t.x*cell+.5,oy+t.y*cell+.5,cell-1,cell-1);}}ctx.restore();const leg=ui.q?.('v15LayerLegend');if(leg)leg.textContent='문화 지도 · 거주 Person의 문화 비율 집계 · 색=주류 문화 · 흐릴수록 혼합도가 높음';}
function ensureMapOption(ui){const sel=ui.q?.('v15LayerSelect')||document.getElementById('v15LayerSelect');if(sel&&!sel.querySelector('option[value="culture33E4"]')){const o=document.createElement('option');o.value='culture33E4';o.textContent='문화 지도';sel.appendChild(o);}}
function culturePanel(v,w){const m=cultureMetrics(v,w);return `<div class="v33e4-culture-panel"><div class="section-head"><div><strong>문화·정체성 V1</strong><div class="small muted">국가와 분리된 실제 Person 문화 구성 · 수도 문화와의 정렬이 자원/산업 산출에 최대 -8%</div></div><span class="tag">${esc(CULTURES[m.capitalPrimary.id]?.name)} ${Math.round(m.capitalPrimary.share*100)}%</span></div><div class="grid"><div class="info"><span class="small muted">수도 문화</span><div>${esc(mixLabel(m.capitalMix))}</div></div><div class="info"><span class="small muted">전국 문화</span><div>${esc(mixLabel(m.nationMix))}</div></div><div class="info"><span class="small muted">평균 수도문화 정렬</span><div class="big">${(m.meanAlignment*100).toFixed(1)}%</div></div><div class="info"><span class="small muted">평균 문화 산출 패널티</span><div class="big">-${(m.avgPenalty*100).toFixed(2)}%</div></div></div><div class="small muted" style="margin-top:7px">혼합문화 Person ${m.mixed}명 (${(m.mixedShare*100).toFixed(1)}%) · Culture 자체는 Nation과 독립적으로 존속</div></div>`;}
function postVillageUI(ui){const v=ui.world?.selectedNation,root=ui.q?.('villageContent');if(!v||!root)return;if((ui.sub==='social'||ui.sub==='residents')&&!root.querySelector('.v33e4-culture-panel'))root.insertAdjacentHTML('afterbegin',culturePanel(v,ui.world));if(ui.sub==='residents'){const ps=(v.residents||[]).filter(p=>p.alive),rows=[...root.querySelectorAll('.resident-row')];for(let i=0;i<Math.min(ps.length,rows.length);i++){const p=ps[i];ensurePerson(p,v,ui.world);let x=rows[i].querySelector('.v33e4-person-culture');if(!x){x=document.createElement('div');x.className='small v33e4-person-culture';rows[i].appendChild(x);}const a=alignment(p,v,ui.world);x.innerHTML=`문화 ${esc(mixLabel(p.cultureMix))} · 수도 정렬 ${(a*100).toFixed(0)}%`;}}
 for(const card of root.querySelectorAll('.settlement-card[data-v17-settlement]')){const id=Number(card.getAttribute('data-v17-settlement'));if(!Number.isFinite(id)||card.querySelector('.v33e4-settlement-culture'))continue;const ps=(v.residents||[]).filter(p=>p.alive&&Number(p.homeTileId)===id);if(!ps.length)continue;const mix=settlementProfile(v,id),p=primary(mix),d=document.createElement('div');d.className='v17-card-extra v33e4-settlement-culture';d.innerHTML=`<span>문화 <b>${esc(CULTURES[p.id]?.name||p.id)}</b> ${Math.round(p.share*100)}%</span><span>${esc(mixLabel(mix,2))}</span>`;card.appendChild(d);}}
function postInspector(ui){const box=ui.q?.('tileInspector');if(!box||ui.world?.selectedTileId==null)return;box.querySelector('.v33e4-inspector-culture')?.remove();const t=ui.world.map.get(Number(ui.world.selectedTileId)),v=t?.ownerId!=null?ui.world.villages.find(x=>Number(x.id)===Number(t.ownerId)):null;if(!v)return;const ps=(v.residents||[]).filter(p=>p.alive&&Number(p.homeTileId)===Number(t.id));if(!ps.length)return;const mix=settlementProfile(v,t.id),p=primary(mix),d=document.createElement('div');d.className='v33e4-inspector-culture small';d.style.marginTop='6px';d.innerHTML=`문화 · <b>${esc(CULTURES[p.id]?.name||p.id)} ${Math.round(p.share*100)}%</b> · ${esc(mixLabel(mix))}`;box.appendChild(d);}
const snapPrev=NS.Telemetry.prototype.snapshot;
NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){attach(w);const s=snapPrev.call(this,w,reason,note);if(!s)return s;let people=0,mixed=0,alignSum=0;for(const row of s.villages||[]){const v=(NS.V035H1B1?.lookupVillage?.(w,row.id)??w.villages.find(x=>Number(x.id)===Number(row.id)));if(!v)continue;const m=cultureMetrics(v,w),n=(v.residents||[]).filter(p=>p.alive).length;people+=n;mixed+=m.mixed;alignSum+=m.meanAlignment*n;const ws=observerWarScan(v,w);Object.assign(row,{capitalPrimaryCulture33E4:m.capitalPrimary.id,capitalPrimaryCultureShare33E4:+m.capitalPrimary.share.toFixed(5),nationPrimaryCulture33E4:m.nationPrimary.id,nationPrimaryCultureShare33E4:+m.nationPrimary.share.toFixed(5),mixedCulturePersons33E4:m.mixed,mixedCultureShare33E4:+m.mixedShare.toFixed(5),meanCapitalCultureAlignment33E4:+m.meanAlignment.toFixed(5),cultureOutputPenaltyAvg33E4:+m.avgPenalty.toFixed(5),warScanTopTarget33E4:ws.target,warScanTopScore33E4:ws.score??'',warScanReason33E4:ws.reason});}const mean=people?alignSum/people:1;Object.assign(s.global,{cultureCount33E4:CULTURE_IDS.length,derivedCultureCount33E4:Object.values(CULTURES).filter(x=>x.derived).length,mixedCulturePersons33E4:mixed,mixedCultureShare33E4:+(people?mixed/people:0).toFixed(5),meanCultureAlignment33E4:+mean.toFixed(5),cultureOutputPenaltyAvg33E4:+(.08*(1-mean)).toFixed(5),cultureMapLayer33E4:1,cultureNameRegistryFamilies33E4:ALL_FAMILIES.length,cultureNameRegistryGiven33E4:ALL_GIVEN.length});return s;};
const csvPrev=NS.Telemetry.prototype.snapshotsCSV;
NS.Telemetry.prototype.snapshotsCSV=function(){const base=csvPrev.call(this),lines=base.split('\n');if(!lines.length)return base;const G=['cultureCount33E4','derivedCultureCount33E4','mixedCulturePersons33E4','mixedCultureShare33E4','meanCultureAlignment33E4','cultureOutputPenaltyAvg33E4','cultureMapLayer33E4','cultureNameRegistryFamilies33E4','cultureNameRegistryGiven33E4'],R=['capitalPrimaryCulture33E4','capitalPrimaryCultureShare33E4','nationPrimaryCulture33E4','nationPrimaryCultureShare33E4','mixedCulturePersons33E4','mixedCultureShare33E4','meanCapitalCultureAlignment33E4','cultureOutputPenaltyAvg33E4','warScanTopTarget33E4','warScanTopScore33E4','warScanReason33E4'],q=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+[...G,...R].map(q).join(',');let i=1;for(const s of this.snapshots||[])for(const row of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+[...G.map(k=>s.global?.[k]),...R.map(k=>row?.[k])].map(q).join(',');}return lines.join('\n');};
