NS.Telemetry.prototype.toJSON=function(w){const d=jsonPrev.call(this,w);d.version='0.33E4';Object.assign(d.worldSummary,{v33E4Revision:REV,cultureIdentity33E4:'Person culture is a sparse 1-3 component mixture; Settlement/Nation culture is derived from real residents while the Nation reference culture is the actual capital resident profile',cultureRegistry33E4:'six founding cultures are independent registry entities; derived/parentCultureIds/originCal/nameSourceCultureWeights schema is reserved for future fusion cultures without enabling fusion generation in E4',cultureOutput33E4:'capital-profile cultural mismatch applies at most 8% loss to Person-produced food/wood/stone/gold/iron-ore and smithy/smelter iron/tools output; combat, health, births and happiness are unchanged',cultureNames33E4:'culture-weighted curated name pools with 1-5 syllable family/given names, shared names, and nation-name reservation for new family generation',cultureMigration33E4:'existing E3 saves receive the founding culture of their current nation at 100%; existing names are preserved; future cross-nation migrants retain their cultureMix',cultureFusion33E4:'schema only; automatic fusion culture emergence is intentionally not implemented',warIntentObserver33E4:'snapshot-only top-candidate score/reason is computed with E2 rawAssessment and then restores estimate caches/counters so peaceful runs can be diagnosed without changing AI state'});return d;};
