 NS.UI.prototype.renderMap=function(){const requested=this.mapLayer||'base';if(requested==='culture33E4'){const keep=this.mapLayer;this.mapLayer='base';try{mapPrev.call(this);}finally{this.mapLayer=keep;}drawCulture(this);return;}return mapPrev.call(this);};
