 NS.UI.prototype.renderCodex=function(){const r=codexPrev.call(this),el=this.q?.('codexContent');if(el&&!el.querySelector('.v33e4-note')){const note=document.createElement('div');note.className='codex-note v33e4-note';note.innerHTML='<strong>V0.33E4 Culture & Identity Foundation V1</strong><br>Person은 1~3개 문화 성분의 cultureMix를 가지며, 수도·정착지·국가 문화는 실제 거주 Person을 집계해 계산합니다. 수도 문화 프로필과의 불일치는 자원·철기 산업 산출에 최대 8%의 마찰만 적용하고 전투·건강·출산·행복에는 직접 영향을 주지 않습니다. 이름은 6개 기초문화의 1~5글자 가중 이름풀에서 생성되며 일부 이름은 문화 간 공유됩니다. 융합문화는 schema만 준비하고 자동 생성하지 않습니다.';(el.querySelector('[data-page="social"]')||el.querySelector('[data-page="war"]')||el).insertAdjacentElement('afterbegin',note);}return r;};
